public class ExpenseReportApproverRequirement : IAuthorizationRequirement
{
}

public class ExpenseReportApproverHandler : AuthorizationHandler<ExpenseReportApproverRequirement, ExpenseReport>
{
    private readonly IExpenseReportRepository _reports;

    public ExpenseReportApproverHandler(IExpenseReportRepository reports)
    {
        _reports = reports;
    }

    protected override async Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        ExpenseReportApproverRequirement requirement,
        ExpenseReport resource)
    {
        var userId = context.User.FindFirstValue(ClaimTypes.NameIdentifier);
        if (userId == null) return;

        var nextApproverId = await _reports.GetNextApproverIdAsync(resource.Id);
        if (nextApproverId == Guid.Parse(userId))
        {
            context.Succeed(requirement);
        }
    }
}

